#!/usr/bin/env python3
"""Extract DCN20 line-buffer accounting used by DCN201, without MMIO code."""
import argparse
import hashlib
import re
from extract_scaler_geometry import ROOT, REF, COMMIT, extract

OUT = ROOT / 'driver/shim/generated/dc_scaler_buffer.inc'


def generate():
    pieces = ['/* SPDX-License-Identifier: MIT */\n'
              '/* Generated by tools/import/extract_scaler_buffer.py. Do not edit.\n'
              f' * PROVENANCE: Linux amdgpu DC, MIT, {COMMIT}. */\n']
    raw = (REF / 'dc_spl_types.h').read_bytes()
    text = raw.decode('utf-8')
    block = re.findall(r'^enum lb_memory_config \{.*?^\};', text, re.M | re.S)
    if len(block) != 1:
        raise ValueError('Expected one lb_memory_config enum')
    pieces += [f'/* dc_spl_types.h, sha256 {hashlib.sha256(raw).hexdigest()} */',
               '// Copyright 2024 Advanced Micro Devices, Inc.', block[0]]
    pieces += ['/* Adapter declarations keep the extracted functions private. */\n'
               'static void dscl2_calc_lb_num_partitions(const struct scaler_data*,\n'
               '    enum lb_memory_config, int*, int*);\n'
               'static bool dpp1_dscl_is_lb_conf_valid(int, int, int);']
    for filename, function in [('dcn20_dpp.c', 'dscl2_calc_lb_num_partitions'),
                               ('dcn10_dpp_dscl.c', 'dpp1_dscl_is_lb_conf_valid')]:
        raw = (REF / filename).read_bytes()
        text = raw.decode('utf-8')
        pieces += [text[:text.index('*/') + 2],
                   f'/* {filename}, sha256 {hashlib.sha256(raw).hexdigest()} */',
                   extract(text, function)]
    return ('\n\n'.join(pieces).rstrip() + '\n').encode('utf-8')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generate()
    if args.check:
        if OUT.read_bytes() != expected:
            raise SystemExit('Scaler buffer extraction is stale')
    else:
        OUT.write_bytes(expected)
    print('Scaler buffer extraction OK')


if __name__ == '__main__':
    main()
